  "sceneId": "4-1",
  "shots": [
    {
      "duration": 7,
      "cast": ["亚瑟", "奥尔德里奇", "塞琳娜"],
      "props": ["行李"],
      "startPosition": "酒馆内光线昏暗，双扇木门紧闭；亚瑟背着行李站在门外，面向木门；奥尔德里奇与塞琳娜并排坐在酒馆内侧桌旁，面向门口方向。",
      "clips": [
        {
          "duration": 5,
          "size": "WS",
          "cameraMove": "固定机位",
          "visualAction": "双扇木门从内侧被推开，阳光照进昏暗酒馆；亚瑟背着行李迈步进门，停在门内侧；镜头带到酒馆内侧桌旁，奥尔德里奇与塞琳娜坐在桌旁。",
          "beat": "建立",
          "sourceBlockIds": ["B01", "B02", "B03"]
        },
        {
          "duration": 2,
          "size": "CU",
          "cameraMove": "跟拍",
          "visualAction": "亚瑟在酒馆内走动，头转向左右环顾四周。",
          "beat": "跟随",
          "sourceBlockIds": ["B04"]
        }
      ]
    },
    {
      "duration": 7,
      "cast": ["亚瑟", "奥尔德里奇", "塞琳娜", "酒馆老板"],
      "props": ["托盘", "啤酒杯"],
      "startPosition": "亚瑟停在门内侧，面向酒馆内部；酒馆老板在吧台与客桌间的过道，双手端托盘，托盘上有三杯啤酒，面向过道前方；奥尔德里奇与塞琳娜坐在桌旁，奥尔德里奇右手放在桌面，塞琳娜双手交叠。",
      "clips": [
        {
          "duration": 2,
          "size": "CU",
          "cameraMove": "跟拍",
          "visualAction": "酒馆老板双手端托盘快步穿过过道，脚下一滑，身体向前倾倒，托盘倾斜。",
          "beat": "触发",
          "sourceBlockIds": ["B05", "B06"]
        },
        {
          "duration": 2,
          "size": "CU",
          "cameraMove": "快速甩镜至手指",
          "visualAction": "托盘上一杯啤酒飞起，酒液洒出；镜头甩向桌旁，奥尔德里奇伸出右手食指，指尖亮起蓝光。",
          "beat": "强调",
          "sourceBlockIds": ["B07", "B08"]
        },
        {
          "duration": 3,
          "size": "CU",
          "cameraMove": "横移跟拍",
          "visualAction": "飞杯和酒液在半空静止；奥尔德里奇挥手，蓝色能量托住酒馆老板，老板踉跄后退撞在桌边；奥尔德里奇收回手，闭眼坐回桌旁，塞琳娜双手交叠坐着。",
          "beat": "转折",
          "sourceBlockIds": ["B09", "B10", "B11"]
        }
      ]
    },
    {
      "duration": 9,
      "cast": ["亚瑟", "奥尔德里奇", "塞琳娜", "酒馆老板"],
      "props": ["金属酒杯", "酒扎", "抹布", "酒杯"],
      "startPosition": "奥尔德里奇闭眼坐在桌旁，右手放在桌面；塞琳娜坐在对面，双手交叠；酒馆老板在桌边站定；亚瑟右手拿着金属酒杯，站在桌旁过道，面向桌子。",
      "clips": [
        {
          "duration": 2,
          "size": "CU",
          "cameraMove": "跟随",
          "visualAction": "亚瑟走到桌旁，拉开椅子坐下，将金属酒杯放到桌上。",
          "beat": "推进",
          "sourceBlockIds": ["B12", "B13"]
        },
        {
          "duration": 4,
          "size": "CU",
          "cameraMove": "固定机位",
          "visualAction": "亚瑟面向前方，开口向老板要酒。",
          "beat": "强调",
          "sourceBlockIds": ["B14", "B15"]
        },
        {
          "duration": 3,
          "size": "CU",
          "cameraMove": "快速横移",
          "visualAction": "酒馆老板放下抹布，快步端来一扎啤酒，将酒倒进金属杯；塞琳娜转头看向亚瑟；奥尔德里奇端起自己的酒杯，斜眼看向亚瑟。",
          "beat": "反应",
          "sourceBlockIds": ["B16", "B17", "B18"]
        }
      ]
    }
  ]
}

