      "clips": [
        {
          "duration": 6,
          "size": "MCU",
          "cameraMove": "固定机位",
          "visualAction": "男酒客站在桌旁大喊；塞琳娜坐在桌旁，右手捂住胸口，睁大双眼抬头看向屋顶。",
          "beat": "反应",
          "sourceBlockIds": ["B37", "B38"]
        },
        {
          "duration": 2,
          "size": "WS",
          "cameraMove": "快速下摇",
          "visualAction": "航拍视角下，一颗燃烧的陨石拖着浓烟从天空坠向森林中的酒馆，红光逼近屋顶。",
          "beat": "钩子",
          "sourceBlockIds": ["B39", "B40"]
        }
      ]
    },
    {
      "duration": 7,
      "cast": ["男酒客", "塞琳娜", "奥尔德里奇"],
